INSERT INTO `llx_cronjob` (`rowid`, `tms`, `datec`, `jobtype`, `label`, `command`, `classesname`, `objectname`, `methodename`, `params`, `md5params`, `module_name`, `priority`, `datelastrun`, `datenextrun`, `datestart`, `dateend`, `datelastresult`, `lastresult`, `lastoutput`, `unitfrequency`, `frequency`, `maxrun`, `nbrun`, `autodelete`, `status`, `processing`, `pid`, `test`, `fk_user_author`, `fk_user_mod`, `fk_mailing`, `note`, `libname`, `email_alert`, `entity`) VALUES
(1, '2026-07-11 10:35:14', '2026-07-11 12:35:14', 'method', 'SendEmailsReminders', '', 'comm/action/class/actioncomm.class.php', 'ActionComm', 'sendEmailsReminder', '', '', 'agenda', 10, NULL, '2026-07-11 12:35:14', '2026-07-11 12:35:14', NULL, NULL, NULL, NULL, '60', 5, 0, 0, 0, 1, 0, NULL, 'isModEnabled(\"agenda\")', NULL, NULL, NULL, 'SendEMailsReminder', '', NULL, 1),
(2, '2026-07-11 10:35:14', '2026-07-11 12:35:14', 'method', 'SendSmsReminders', '', 'comm/action/class/actioncomm.class.php', 'ActionComm', 'sendSmsReminder', '', '', 'agenda', 10, NULL, '2026-07-11 12:35:14', '2026-07-11 12:35:14', NULL, NULL, NULL, NULL, '60', 5, 0, 0, 0, 1, 0, NULL, 'isModEnabled(\"agenda\")', NULL, NULL, NULL, 'SendSmsReminder', '', NULL, 1),
(3, '2026-07-11 10:36:48', '2026-07-11 12:36:48', 'method', 'RecurringSupplierInvoicesJob', '', 'fourn/class/fournisseur.facture-rec.class.php', 'FactureFournisseurRec', 'createRecurringInvoices', '', '', 'fournisseur', 51, NULL, '2026-07-11 12:36:48', '2026-07-11 23:00:00', NULL, NULL, NULL, NULL, '86400', 1, 0, 0, 0, 1, 0, NULL, 'isModEnabled(\"supplier_invoice\")', 1, 1, NULL, 'Generate recurring supplier invoices', '', NULL, 1),
(4, '2026-07-11 10:36:48', '2026-07-11 12:36:48', 'method', 'SendEmailsRemindersOnSupplierInvoiceDueDate', '', 'fourn/class/fournisseur.facture.class.php', 'FactureFournisseur', 'sendEmailsRemindersOnSupplierInvoiceDueDate', '10,all,EmailTemplateCode,duedate', '', 'fournisseur', 50, NULL, '2026-07-11 12:36:48', '2026-07-11 23:00:00', NULL, NULL, NULL, NULL, '86400', 1, 0, 0, 0, 0, 0, NULL, 'isModEnabled(\"supplier_invoice\")', 1, 1, NULL, 'Send an email when we reach the supplier invoice due date (or supplier invoice date) - n days. First param is n, the number of days before due date (or supplier invoice date) to send the remind (or after if value is negative), second parameter is \"all\" or a payment mode code, third parameter is the code of the email template to use (an email template with the EmailTemplateCode must exists. The version of the email template in the language of the thirdparty will be used in priority. Language of the thirdparty will be also used to update the PDF of the sent supplier invoice). The fourth parameter is the string \"duedate\" (default) or \"invoicedate\" to define which date of the supplier invoice to use.', '', NULL, 1),
(5, '2026-07-11 10:36:51', '2026-07-11 12:36:51', 'method', 'RecurringInvoicesJob', '', 'compta/facture/class/facture-rec.class.php', 'FactureRec', 'createRecurringInvoices', '', '', 'facture', 51, NULL, '2026-07-11 12:36:51', '2026-07-11 23:00:00', NULL, NULL, NULL, NULL, '86400', 1, 0, 0, 0, 1, 0, NULL, 'isModEnabled(\"invoice\")', 1, 1, NULL, 'Generate recurring invoices.', '', NULL, 1),
(6, '2026-07-11 10:36:51', '2026-07-11 12:36:51', 'method', 'SendEmailsRemindersOnInvoiceDueDate', '', 'compta/facture/class/facture.class.php', 'Facture', 'sendEmailsRemindersOnInvoiceDueDate', '10,all,EmailTemplateCode,duedate', '', 'facture', 50, NULL, '2026-07-11 12:36:51', '2026-07-11 23:00:00', NULL, NULL, NULL, NULL, '86400', 1, 0, 0, 0, 0, 0, NULL, 'isModEnabled(\"invoice\")', 1, 1, NULL, 'Send an email when we reach the invoice due date (or invoice date) - n days. First param is n, the number of days before due date (or invoice date) to send the remind (or after if value is negative), second parameter is \"all\" or a payment mode code, third parameter is the code of the email template to use (an email template with the EmailTemplateCode must exists. The version of the email template in the language of the thirdparty will be used in priority. Language of the thirdparty will be also used to update the PDF of the sent invoice). The fourth parameter is the string \"duedate\" (default) or \"invoicedate\" to define which date of the invoice to use.', '', NULL, 1);
